from promote_l251_l270_common import run_batch

FD="src.book.reis-housley-fundamentals-data-engineering"; DD="src.book.kleppmann-ddia.1e"; DI="src.web.dbt-incremental-models"
DT="src.web.dbt-data-tests"; DJ="src.web.dbt-jinja-macros"; DM="src.web.dbt-materializations"
FDL="SRC-REIS-HOUSLEY-FUNDAMENTALS-DATA-ENGINEERING"; DDL="SRC-KLEPPMANN-DDIA-1E"; DIL="SRC-DBT-INCREMENTAL-MODELS"
DTL="SRC-DBT-DATA-TESTS"; DJL="SRC-DBT-JINJA-MACROS"; DML="SRC-DBT-MATERIALIZATIONS"

LESSONS=(
Lesson(256,"Lesson_256-generic-tests-and-their-limits","Generic Tests and Their Limits","144-generic-tests-and-their-limits.md","wiki.transformation.dbt-generic-tests-limits","Generic tests bắt được lớp lỗi nào, và lớp guarantee nào chúng không thể cung cấp nếu thiếu boundary, severity và coverage design?",(DT,FD),(DTL,FDL),(
("Test trả về failing rows","Data test là query mà các row trả về đại diện vi phạm. Generic test đóng gói cùng assertion để áp vào model, column, source hoặc resource khác bằng arguments. `not_null`, `unique`, `relationships` và `accepted_values` diễn đạt constraints thường gặp, nhưng tên test không thay grain statement. Một uniqueness test trên `order_id` sai cột có thể pass hoặc fail mà không nói được grain thật. Test definition, arguments, config và selected resource cùng tạo semantics."),
("Bốn generic tests không phải data quality đầy đủ","Not-null không phát hiện sentinel hay logically missing values. Unique có thể xử lý NULL và collation theo engine. Relationships kiểm referential subset tại thời điểm query nhưng không chứng minh temporal alignment hoặc one-to-one. Accepted values cần policy cho new/unknown code và effective dates. Cả bốn không kiểm completeness so với source, aggregate reconciliation, late data, freshness hoặc cross-row business equations nếu chưa thêm assertion."),
("Scope severity store failures","Test chỉ chạy trên selection và dataset hiện tại. `where`, limit, sampling hoặc recent partitions làm coverage có chủ đích nhưng phải hiển thị. Severity warn có thể cho pipeline tiếp tục; error cũng chỉ chặn theo command/orchestrator policy. Store failures hữu ích cho triage nhưng chứa dữ liệu nhạy cảm và cần access/retention. Một test xanh khi bảng rỗng thường vô nghĩa nếu absence không được kiểm riêng."),
("Threshold không được che lỗi","`warn_if`/`error_if` và tolerance phù hợp cho noisy rule có denominator rõ. Absolute 100 failed rows khác 100/100 và 100/1e9. Threshold có owner, business cost, baseline và expiry; không tăng ngưỡng chỉ để CI xanh. Test result cần failing count, population count, rate và sample locator. Exact constraints như primary business key thường không nên dùng tolerance trừ khi exception ledger được quản trị."),
("Placement và duplication","Đặt assertion gần layer sở hữu semantics: source/staging cho source contract, mart cho consumer invariant. Lặp cùng test ở mọi layer tăng runtime và alert fatigue mà không tăng detection. Tuy nhiên test tại publication boundary có thể cần dù upstream đã có để bắt transformation regressions. Map each failure to owner, containment và downstream impact. Test package macro phải pin version và review compiled SQL."),
("Mutation lab","Tạo fixture với null, duplicate, orphan, unexpected enum, empty table, late partition và compensating aggregate error. Chạy generic tests với severity/where khác nhau; inspect compiled SQL và failure rows. Chứng minh cases lọt qua rồi bổ sung singular/reconciliation checks. Đạt khi learner nêu coverage denominator, false-positive/negative và operation khi fail thay vì liệt kê bốn tên test."),
),tuple(f"Generic-test probe {i}: assertion SQL, population, failure row, severity và uncovered guarantee phải rõ" for i in range(1,16))),
Lesson(257,"Lesson_257-singular-tests-for-business-invariants","Singular Tests for Business Invariants","145-singular-tests-business-invariants.md","wiki.transformation.dbt-singular-business-invariants","Viết singular test thế nào để một business invariant trả về counterexample tối thiểu, chẩn đoán được và không phụ thuộc accidental grain?",(DT,DD),(DTL,DDL),(
("Invariant trước SQL","Invariant là mệnh đề phải đúng trong scope: mỗi paid order có payment coverage; daily closing balance nối đúng prior day; booked revenue bằng sum allocations theo currency policy. Nêu grain, time boundary, exclusions, tolerance và owner trước query. Singular test trả về rows vi phạm, không trả summary boolean khó điều tra. Một test không có written invariant dễ trở thành query lạ mà người sau không biết sửa data hay sửa test."),
("Counterexample shape","Output failure gồm stable keys, observed/expected values, diff, boundary/version và reason fields đủ triage; tránh select toàn bộ PII. Aggregate invariant cần join-back keys hoặc grouped counterexample. Test query phải deterministic và không duplicate violations do fanout. Dùng CTE đặt actual, expected, comparison rõ. Empty expected set cần explicit check để test không pass vacuously."),
("Temporal và numeric semantics","Time-based invariant pin timezone, half-open interval, late-data delay và snapshot boundary. Decimal/currency dùng type/rounding policy; floating equality cần tolerance có scale. Status transitions kiểm valid sequences và event ordering, không chỉ current value. Slowly changing dimensions cần as-of join. Một test chạy trong khi upstream đang publish có thể thấy mixed state; schedule after atomic publication hoặc use common snapshot."),
("Severity và ownership","Critical invariant gắn error/stop publication; diagnostic heuristic có thể warn nhưng phải có disposition. Owner nhận failing rows, runbook, retry/retest và waiver expiry. Known exceptions nằm trong versioned exception table với reason/approval, không hard-code key list trong SQL. Nếu exception population tăng, alert separate. Test failure không tự quyết rollback nếu output already public; orchestration policy phải nối test gate với publish."),
("False confidence","Singular test chỉ kiểm data hiện có và query logic của chính nó. Same bug có thể nằm trong model và expected calculation nếu reuse logic. Independent oracle dùng raw/source boundary hoặc alternate formulation. Passing test không chứng minh source completeness. Mutation testing chủ động phá row để chứng minh test fail đúng direction; negative control phát hiện test không được selected/running."),
("Invariant suite lab","Dựng orders/payments/refunds/FX fixture, inject fanout, missing payment, duplicate allocation, currency mix, late refund và exception. Viết 3 invariants có minimal failure rows, chạy mutation matrix, đo runtime và inspect selected tests. Reviewer tái hiện một failure từ keys. Đạt khi rule có owner, boundary, threshold và recovery, đồng thời full recomputation xác nhận test không đồng bug với model."),
),tuple(f"Singular-test probe {i}: invariant, counterexample grain, independent oracle, owner và publish gate phải rõ" for i in range(1,16))),
Lesson(258,"Lesson_258-jinja-and-macros-where-abstraction-stops-paying","Jinja and Macros Where Abstraction Stops Paying","146-jinja-macros-abstraction-boundary.md","wiki.transformation.dbt-jinja-macro-boundary","Macro nào thật sự loại bỏ một policy lặp lại, và khi nào abstraction che SQL đến mức review, lineage và debugging đắt hơn phần code tiết kiệm?",(DJ,DT),(DJL,DTL),(
("Jinja sinh SQL","Expressions emit text, statements điều khiển template, macros nhận arguments và trả SQL/text; warehouse chỉ thấy compiled SQL. Vì vậy review cần cả source template lẫn compiled output. Jinja truthiness, quoting, whitespace và parse/execute context khác SQL semantics. Macro có thể gọi adapter dispatch/introspection, làm output phụ thuộc target. Không debug macro chỉ bằng nhìn model gọi nó."),
("Abstraction trả giá bằng indirection","Macro tốt nắm một policy ổn định: safe casting, standardized surrogate key, grant convention hoặc repeated test assertion. Macro kém giấu business rule riêng của một model, nhận hàng chục flags hoặc tạo SQL khác mạnh theo environment. DRY không phải mục tiêu tối cao; ba dòng SQL rõ có thể rẻ hơn một abstraction mà reviewer phải mentally execute. Đo call sites, change coupling và debug path."),
("Interface contract","Document macro purpose, arguments/types/defaults, return shape, side effects, supported adapters và failure behavior. Validate identifiers/literals đúng context; không nối untrusted strings tùy ý. Namespace package macros. Breaking signature/output change cần version/migration. Macro output ảnh hưởng grain hoặc column set phải có compile fixtures và downstream contract tests. Do not use environment conditionals to silently change business semantics."),
("Parse execute và introspection","`execute` phân biệt parse from execution contexts; queries/introspection chỉ hợp lệ khi connection available. Code phải trả graph-consistent output ở parse path và fail rõ ở runtime path. `run_query` có cost, permissions và nondeterminism nếu metadata/source state đổi giữa compile and run. Cache assumptions phải nêu. Macros dùng current timestamp/randomness phá deterministic compilation và state comparison."),
("Test macro như compiler","Compile representative calls across adapter targets/configurations; compare normalized expected SQL/golden snapshots và then execute semantic fixtures. Include empty list, reserved identifier, null argument, unusual schema, large column list và unsupported adapter. Golden SQL bắt drift nhưng có thể overfit whitespace; semantic test bắt behavior. Package upgrade chạy same matrix và inspect manifest macro dependencies."),
("Refactor decision","Bắt đầu từ duplicated policy chứ không từ desire to be clever. Extract smallest stable unit, keep model grain visible, name arguments in domain terms, limit branching và provide escape hatch only with explicit review. Nếu call sites cần đọc macro source mỗi lần để hiểu query, abstraction chưa trả lợi. Reversal trigger: adapter divergence, branching complexity hoặc incident/debug time vượt maintenance saved."),
),tuple(f"Macro probe {i}: call, compiled SQL, semantic fixture, adapter branch và readability cost phải rõ" for i in range(1,16))),
Lesson(259,"Lesson_259-incremental-models-the-is-incremental-contract","Incremental Models and the is_incremental Contract","147-incremental-models-is-incremental-contract.md","wiki.transformation.dbt-is-incremental-contract","`is_incremental()` cần những điều kiện, filter symmetry và replay assumptions nào để incremental state hội tụ với full recomputation?",(DI,DD),(DIL,DDL),(
("Ba điều kiện chỉ mở branch","`is_incremental()` true khi target tồn tại dạng table, model configured incremental và không chạy full refresh. Nó không xác nhận unique key, source watermark, target completeness hay schema compatibility. SQL phải hợp lệ ở cả true/false branches. Một target table tồn tại từ run lỗi vẫn có thể mở incremental path. Preflight cần relation identity, schema/version và bootstrap contract ngoài macro boolean."),
("Filter xác định change population","Incremental predicate chọn records cần xử lý từ source và đôi khi giới hạn existing target scan. Chọn boundary bằng source updated/commit time, stable tie key và overlap cho late visibility. `max(updated_at)` target có NULL/empty/stale problems, và output timestamp có thể khác source cursor. Filter đặt sớm giảm scan nhưng không được đổi semantics. Ghi inclusive/exclusive rule và timezone."),
("Same SQL two semantics","Full path định nghĩa canonical result; incremental path phải là algebraic delta đưa prior valid target tới cùng result. Joins, windows và aggregates thường cần dependency lookback rộng hơn changed rows. Một changed order có thể đổi customer lifetime total; filter order rows rồi group riêng tạo wrong total. Recompute affected keys/partitions or merge with prior state theo proof. Compile both branches and compare on change scenarios."),
("Unique key delete schema","Unique key ổn định theo model grain; nonunique/null keys gây nondeterministic merge hoặc duplicate. Updates need precedence/version; hard deletes need tombstone, invalidation or partition replacement. `on_schema_change` behavior không backfill historical values và tùy adapter. Column logic change có thể yêu cầu full refresh. Contract nêu policy cho add/drop/type/semantic changes."),
("Checkpoint và target state","Target đôi khi đóng vai checkpoint qua max value; coupling này dễ hỏng khi partial publish, manual edit hoặc retention. Better track input boundary/run ledger where needed. Atomic materialization semantics phụ thuộc adapter. Crash before/after merge, hook và artifact upload cần rerun convergence. Side effects ngoài target cũng cần idempotency identity."),
("Equivalence lab","Generate mutable entities/events with late update, delete, duplicate key, same timestamp ties, schema add và logic change. Run full baseline; then incremental sequences with kills/reorders; compare key set, typed row hash and aggregates. Periodically full-refresh/reconcile. Đạt khi documented horizon covers observed late data, every divergence maps to recovery and incremental output equals full under stated assumptions."),
),tuple(f"is_incremental probe {i}: branch condition, source filter, affected state, rerun và full-equivalence oracle phải rõ" for i in range(1,16))),
Lesson(260,"Lesson_260-incremental-strategies-by-adapter","Incremental Strategies by Adapter","148-incremental-strategies-by-adapter.md","wiki.transformation.dbt-incremental-strategies-adapter","Append, merge, delete-insert, insert-overwrite và microbatch khác nhau ra sao theo adapter, key, partition và transaction boundary?",(DI,DM,FD),(DIL,DML,FDL),(
("Strategy là adapter implementation","Tên strategy map tới macros/DDL riêng của adapter và warehouse. Cùng `merge` có support, syntax, matching, transaction, schema and performance khác nhau. Pin dbt-core, adapter và platform; inspect compiled/run SQL. Unsupported option phải fail configuration hoặc test, không silently assume fallback. Decision dựa capability matrix từ docs plus sandbox observation."),
("Append","Append chỉ insert output slice, phù hợp immutable events có deterministic identity/dedup downstream. Mutable rows tạo versions/duplicates. Retry same slice duplicates nếu no idempotent guard. Lowest write coordination đổi lấy consumer complexity. Test duplicate delivery, overlapping windows và same identity different payload; metric includes inserted vs replayed records."),
("Merge và delete-insert","Merge matches unique key then updates/inserts; duplicate source keys may error or resolve unpredictably, and absent source row is not delete unless explicit. Delete-insert removes matched keys then inserts replacement; crash/transaction boundary can expose gap if not atomic. Both need stable grain, affected key set, precedence and hard-delete policy. Target scan predicates improve cost but can miss old matching rows if too narrow."),
("Insert overwrite","Overwrite replaces partitions or scopes, good when change set aligns with complete partition boundary. Late data inside selected partitions converges; partial source slice can erase valid rows. Dynamic/static partition semantics and atomicity vary. Prove list of replaced partitions, complete reconstruction and no out-of-scope deletion. Large partition rewrite may exceed cost/SLO despite simple correctness."),
("Microbatch","Microbatch divides event-time range into bounded batches with framework/adapter behavior; it needs event-time column, batch size, lookback, concurrency and failure/retry contract. Batches are not automatically independent when aggregations/windows cross boundaries. Parallelism can violate ordering or shared dimension assumptions. Validate batch metadata and final equivalence, not just each batch success."),
("Capability ADR","For each adapter candidate, record supported strategies, unique-key needs, predicate placement, transaction/publication scope, schema change, parallelism, SQL output and known limitations. Run same change fixture across strategies; measure correctness, target/source scan, write amplification, lock time and recovery. Choose smallest semantics meeting contract and name trigger to switch when volume/change shape changes."),
),tuple(f"Adapter-strategy probe {i}: compiled operation, key/partition scope, transaction window, recovery và equivalence phải rõ" for i in range(1,16))),
)
QUERIES={256:["Generic dbt tests có giới hạn gì?","Test severity và threshold nên thiết kế thế nào?","Vì sao test xanh trên bảng rỗng chưa đủ?"],257:["Singular test trả về gì?","Business invariant cần boundary nào?","Mutation testing data test để làm gì?"],258:["Khi nào nên viết dbt macro?","Macro abstraction quá mức có dấu hiệu gì?","Kiểm compiled SQL của macro thế nào?"],259:["is_incremental true khi nào?","Incremental equivalence với full refresh chứng minh ra sao?","Incremental filter cần tie và overlap thế nào?"],260:["Incremental strategy phụ thuộc adapter ra sao?","Insert overwrite an toàn khi nào?","Microbatch có assumption gì?"]}
VERIFY={n:"Dùng project tối thiểu và fixture có mutations đã biết; compile exact node/branch, execute trong sandbox nếu có, lưu artifacts rồi so key set, typed hashes và business invariants với full/reference computation." for n in range(256,261)}
TAKEAWAYS={256:"Generic tests là reusable failing-row queries; chúng chỉ bảo đảm assertion, population và severity đã cấu hình, không thay completeness hay business reconciliation.",257:"Singular test tốt biến invariant thành counterexample tối thiểu có owner và boundary; query tự tính expected bằng cùng bug không phải independent proof.",258:"Macro chỉ đáng giá khi đóng gói policy ổn định mà vẫn để grain và compiled SQL dễ review; DRY quá mức làm tăng incident-debug cost.",259:"Incremental correctness là equivalence claim với canonical full result dưới stated mutations, lateness và delete assumptions; `is_incremental()` chỉ chọn branch.",260:"Incremental strategy là contract của adapter/warehouse cụ thể; tên append, merge hay overwrite không cung cấp atomicity hoặc recovery phổ quát."}
